create temporary table stock_baseline on commit drop as select id from public.category_runtime_review_v16_2 where computed_playable_v16_2;
do $guard$ begin
 if (select count(*) from stock_baseline)<>410 then raise exception 'Catalog baseline changed'; end if;
 if (select count(*) from stock_repair)<>4 then raise exception 'Expected four stock categories'; end if;
 if exists(select 1 from stock_repair p join public.category_runtime_review_v16_2 v on v.id=p.id where v.editorial_status in ('rejected','duplicate') or v.duplicate_of is not null or v.subjective_or_composite or v.political_self_reported or v.stale_data) then raise exception 'Protected category'; end if;
 if exists(select 1 from stock_repair p join public.stat_categories c on c.id=p.id where c.source_organization<>'FAOSTAT' or c.common_year<>(p.data->'source'->>'year')::int or c.source_query->>'itemCode'<>p.data->'source'->'source_query'->>'itemCode' or c.source_query->>'elementCode'<>p.data->'source'->'source_query'->>'elementCode') then raise exception 'Source identity changed'; end if;
 if exists(select 1 from stock_repair p join public.stat_observations o on o.category_id=p.id where p.id not like '%camels%') then raise exception 'Poultry rows no longer empty; re-audit required'; end if;
end $guard$;
insert into public.category_recovery_evidence_v16_3_4(category_id,rules_version,snapshot_fingerprint,dependency_fingerprints,proofs,allow_quality_floor,rationale,previous_state,approved)
select p.id,'16.3.4','pending','{}',p.data->'proofs',p.id like '%camels%',
'Official QCL archive fetched 2026-09-07 and independently extracted. Poultry values converted from thousand animals; camel values compared exactly. Twelve complete production-solver witnesses. Missing values are not zeros.',
jsonb_build_object('category',to_jsonb(c),'review',to_jsonb(r),'observations',coalesce((select jsonb_agg(to_jsonb(o)) from public.stat_observations o where o.category_id=p.id),'[]'::jsonb)),false
from stock_repair p join public.stat_categories c on c.id=p.id join public.category_review_state r on r.category_id=p.id;
insert into public.stat_observations(category_id,country_iso3,country_name,data_year,value,source_url,source_record_id,metadata)
select p.id,o.country_iso3,o.country_name,o.data_year,o.value,o.source_url,o.source_record_id,o.metadata
from stock_repair p cross join lateral jsonb_to_recordset(p.data->'source'->'observations') as o(country_iso3 text,country_name text,data_year int,value numeric,source_url text,source_record_id text,metadata jsonb)
where p.id not like '%camels%';
insert into public.category_review_contracts_v16_3_4 as contract(category_id,review_patch,presentation_patch)
select p.id,'{"status":"approved"}'::jsonb,
jsonb_build_object('plain_language_description',p.data->'patch'->'plain_language_description','measurement_type','total','metadata',p.data->'patch'->'metadata')
from stock_repair p
on conflict(category_id) do update set review_patch=contract.review_patch||excluded.review_patch,presentation_patch=contract.presentation_patch||excluded.presentation_patch,revision=contract.revision+1,updated_at=now();
update public.stat_categories c set unit='animals',value_type='total',measurement_type='total',
plain_language_description=p.data->'patch'->>'plain_language_description',
technical_definition=p.data->'patch'->>'technical_definition',unit_explanation=p.data->'patch'->>'unit_explanation',
source_query=p.data->'patch'->'source_query',metadata=p.data->'patch'->'metadata',
content_review_status='approved',curation_status='approved',player_quality_status='approved',
updated_at=now()
from stock_repair p where c.id=p.id;
do $audit$
declare p record; expected int; actual int; checksum text;
begin
 for p in select * from stock_repair loop
  expected:=(p.data->'source'->>'coverage')::int;
  select count(*),md5(string_agg(o.country_iso3||':'||encode(float8send(o.value::float8),'hex'),',' order by o.country_iso3)) into actual,checksum
  from public.stat_observations o where o.category_id=p.id and o.data_year=(p.data->'source'->>'year')::int;
  if actual<>expected or exists(
   select 1 from jsonb_to_recordset(p.data->'source'->'observations') as x(country_iso3 text,data_year int,value numeric)
   left join public.stat_observations o on o.category_id=p.id and o.country_iso3=x.country_iso3 and o.data_year=x.data_year
   where o.value is distinct from x.value) then raise exception 'Official source comparison failed: %',p.id; end if;
  perform public.record_category_validation(p.id,'verified','geostats-v16.3.4-official-qcl-stock-recovery',
  (p.data->'source'->>'year')::int,expected,actual,actual,0,0,checksum,checksum,
  '{"source_organization":true,"source_dataset":true,"source_indicator_code":true,"item_code":true,"element_code":true,"query_year":true,"unit":true,"measure_semantics":true}'::jsonb,null,
  jsonb_build_object('newSourceFetch',true,'archiveSha256','c5835418c18f9322e7decbd6800f93a216eaae3cdfa31acb08f0518c0c6d6853','sourceUrl','https://bulks-faostat.fao.org/production/Production_Crops_Livestock_E_All_Data_(Normalized).zip','conversion','1000 An multiplied by 1000; An unchanged','missingCountriesAreZero',false),null);
 end loop;
end $audit$;
select public.refresh_v16_2_runtime_catalog();
do $preserve$ begin
 if exists(select 1 from stock_baseline b left join public.category_runtime_review_v16_2 v on v.id=b.id where not coalesce(v.computed_playable_v16_2,false)) then raise exception 'Baseline category regressed'; end if;
end $preserve$;
commit;
